// Claudeのレスポンス(content[0].text にJSON配列文字列)をパースしてitem化する
const raw = $input.first().json.content?.[0]?.text ?? '[]';
let parsed;
try {
  const match = raw.match(/\[[\s\S]*\]/);
  parsed = JSON.parse(match ? match[0] : raw);
} catch (e) {
  throw new Error('Claude応答のJSONパースに失敗しました: ' + raw.slice(0, 200));
}
return parsed.map(p => ({
  json: {
    platform: p.platform,
    post_type: p.post_type,
    target_persona: p.target_persona,
    source_summary: p.source_summary
  }
}));
